import{_ as t,o as a,c as r,a3 as n}from"./chunks/framework.DQ-7HQaQ.js";const p=JSON.parse('{"title":"Chunking, source structure and retrieval","description":"Learn how to divide documents without losing meaning, compare two strategies, and evaluate evidence using existing IS373 sources.","frontmatter":{"title":"Chunking, source structure and retrieval","description":"Learn how to divide documents without losing meaning, compare two strategies, and evaluate evidence using existing IS373 sources."},"headers":[],"relativePath":"students/chunking.md","filePath":"students/chunking.md","lastUpdated":1794433168000}'),o={name:"students/chunking.md"};function s(i,e,d,h,c,l){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="chunking-where-should-we-cut-a-document" tabindex="-1">Chunking: where should we cut a document? <a class="header-anchor" href="#chunking-where-should-we-cut-a-document" aria-label="Permalink to &quot;Chunking: where should we cut a document?&quot;">​</a></h1><p>A company has an employee handbook. An assistant must answer: <strong>“Who approves a travel reimbursement?”</strong> The answer is in one paragraph, but the word <strong>“approves”</strong> is on one page and the approving job title is on the next. A careless split can separate the question from its answer.</p><p><strong>Chunking means dividing source material into manageable, retrievable pieces.</strong> Each piece should carry its original source ID and location. We chunk to fit processing limits, improve retrieval granularity, and avoid passing entire documents to every model call.</p><p>There is no universally best chunk size: good boundaries depend on the document, the questions and the embedding/retrieval method. <a href="https://www.pinecone.io/learn/chunking-strategies/" target="_blank" rel="noreferrer">Pinecone&#39;s technical overview</a> discusses these tradeoffs.</p><h2 id="one-fictional-example" tabindex="-1">One fictional example <a class="header-anchor" href="#one-fictional-example" aria-label="Permalink to &quot;One fictional example&quot;">​</a></h2><p>```text SOURCE: S-events — Harbor Club bulletin, section &quot;Events&quot; [Paragraph 1] The Events Committee organizes monthly workshops. [Paragraph 2] Visitors must sign in at the welcome desk. [Paragraph 3] The date of the next annual meeting has not been announced. ```</p><p><strong>Option A: fixed-size character chunks.</strong> Easy to implement, but a boundary could split “Events Committee organizes” across two chunks. <em>Characters and model tokens are not interchangeable units.</em></p><p><strong>Option B: paragraph/heading chunks.</strong> Keeps each statement together and helps preserve the section title, but a paragraph can be too long or need neighboring context.</p><p>Both methods must preserve source metadata. <strong>Chunk S-events-C02 is not a separate publication or verified fact.</strong> It is a slice of source S-events.</p><h2 id="choose-a-boundary-deliberately" tabindex="-1">Choose a boundary deliberately <a class="header-anchor" href="#choose-a-boundary-deliberately" aria-label="Permalink to &quot;Choose a boundary deliberately&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Strategy</th><th>Why developers use it</th><th>Common failure</th></tr></thead><tbody><tr><td>Fixed length</td><td>Simple, predictable processing limits</td><td>Breaks sentences, tables, names or claims</td></tr><tr><td>Sliding window/overlap</td><td>Carries some context across boundaries</td><td>Duplicates content, increases cost and may skew rankings</td></tr><tr><td>Paragraph or heading</td><td>Respects the author&#39;s structure</td><td>Oversized paragraphs, uneven chunk lengths</td></tr><tr><td>Recursive splitting</td><td>Tries larger boundaries then smaller ones</td><td>Still depends on length limits and separators</td></tr><tr><td>Semantic splitting</td><td>Tries to keep related ideas together</td><td>Requires extra modeling, cost and tuning</td></tr><tr><td>Parent-child retrieval</td><td>Search small units, return a larger parent section</td><td>More complex indexing and source mapping</td></tr></tbody></table><p><strong>Start simple.</strong> An exact, verified example beats a sophisticated algorithm whose outputs you cannot inspect.</p><h2 id="the-metadata-that-makes-retrieval-trustworthy" tabindex="-1">The metadata that makes retrieval trustworthy <a class="header-anchor" href="#the-metadata-that-makes-retrieval-trustworthy" aria-label="Permalink to &quot;The metadata that makes retrieval trustworthy&quot;">​</a></h2><p>Each stored chunk should identify:</p><p>```text source_id S-events source_version 2026-11-11-teaching-fixture chunk_id S-events-C02 ordinal 2 source_location section: Events / paragraph: 2 text Visitors must sign in at the welcome desk. chunk_method paragraph ```</p><p>This is an illustrative record, not proof that every field exists in our teaching script. If a source changes, decide what to reprocess and how outdated chunks/vectors stop being returned. Stable source identity and source version are more important than pretending generated chunk numbers never change.</p><h2 id="two-experiments-you-can-do-without-an-api-key" tabindex="-1">Two experiments you can do without an API key <a class="header-anchor" href="#two-experiments-you-can-do-without-an-api-key" aria-label="Permalink to &quot;Two experiments you can do without an API key&quot;">​</a></h2><p><strong>Experiment A — inspect the actual importer.</strong> Open the <a href="https://github.com/kaw393939/is373-rag/blob/main/student-reference/rag_lab.py" target="_blank" rel="noreferrer">reference code</a>. Find the `paragraphs()` function, then inspect one <a href="https://github.com/kaw393939/is373-rag/blob/main/student-reference/fixtures/events.txt" target="_blank" rel="noreferrer">fictional source file</a>. Predict how many chunks it creates. Run the <a href="./reference#your-first-15-minutes">15-minute lab</a> and inspect real chunk text and `ordinal`.</p><p><strong>Experiment B — compare a proposed different split.</strong> In a copied test fixture, place a key sentence across an artificial 60-character boundary. Ask an AI coding agent to propose a fixed-character splitter and a paragraph splitter as <strong>separate experiments</strong>. Compare what each returns to <strong>“Who organizes workshops?”</strong> Keep the original fixture unchanged, save actual outputs and decide which split better preserves support.</p><p>We deliberately do not provide a “magic 500-token” rule. The right experiment specifies <strong>characters or tokens, a tokenizer when relevant, source and version, chunk count, retrieved IDs, and the query</strong>. Larger chunks can hide precise answers; tiny chunks can lose context.</p><h2 id="evaluate-the-result-before-changing-your-design" tabindex="-1">Evaluate the result before changing your design <a class="header-anchor" href="#evaluate-the-result-before-changing-your-design" aria-label="Permalink to &quot;Evaluate the result before changing your design&quot;">​</a></h2><p>For one supported, one paraphrased, and one unanswerable question, record:</p><ol><li><strong>Expected source/passage</strong> before execution.</li><li><strong>Retrieved chunk IDs and text</strong>, not just the model&#39;s explanation.</li><li>Whether the boundary preserved the entire fact or relationship.</li><li>Whether the actual answer&#39;s citations support each claim.</li><li>One change and a repeat run. Is retrieval better, worse or merely different?</li></ol><p>When a citation fails, investigate retrieval and source boundaries <strong>before</strong> asking the model to sound more certain.</p><h3 id="ask-an-ai-coding-partner" tabindex="-1">Ask an AI coding partner <a class="header-anchor" href="#ask-an-ai-coding-partner" aria-label="Permalink to &quot;Ask an AI coding partner&quot;">​</a></h3><p>```text Read my existing importer and my permitted source fixture. Show me its actual chunking rule; don&#39;t assume it uses tokens. Predict, then run the import and display source IDs, chunk IDs, text and source locations. Compare paragraph/heading boundaries with a second small strategy without replacing the first. Use the same three evaluation questions. Show any split claim, duplication or lost context, and record actual results. Do not install a framework or change my production import until I approve. Ask me which strategy I prefer and what evidence supports that choice. ```</p><h3 id="a-note-from-the-ai" tabindex="-1">A note from the AI <a class="header-anchor" href="#a-note-from-the-ai" aria-label="Permalink to &quot;A note from the AI&quot;">​</a></h3><blockquote><p>I might retrieve a passage that sounds relevant while leaving out its exception on the next line. Before trusting the answer, inspect <strong>what the chunk includes and what it excludes</strong>. Retrieval is a software design choice, not an oracle.</p></blockquote><h2 id="more-to-explore" tabindex="-1">More to explore <a class="header-anchor" href="#more-to-explore" aria-label="Permalink to &quot;More to explore&quot;">​</a></h2><ul><li><a href="./embeddings">Embeddings handout</a>: numerical representations are computed <strong>after</strong> you select an input unit.</li><li><a href="./library-survey">AI library survey</a>: optional splitters and pipelines, including LangChain.</li><li><a href="https://github.com/kaw393939/is373-studio/blob/main/docs/handouts/database-rag-research.md" target="_blank" rel="noreferrer">Original IS373 RAG research handout</a>: assignment-aligned comparison.</li><li><a href="https://www.pinecone.io/learn/chunking-strategies/" target="_blank" rel="noreferrer">Pinecone chunking strategies</a>: practical tradeoffs and advanced methods.</li></ul><p><em>Fictional scenario and proposed experiments. No example claims a model was run or a benchmark was measured.</em></p>',31)])])}const g=t(o,[["render",s]]);export{p as __pageData,g as default};
